import{_ as t,c as e,o as a,a4 as o}from"./chunks/framework.NcOuGTBf.js";const f=JSON.parse('{"title":"网络","description":"","frontmatter":{},"headers":[],"relativePath":"server/network/index.md","filePath":"server/network/index.md"}'),r={name:"server/network/index.md"},s=o('<h1 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h1><h2 id="_1、http缓存原理" tabindex="-1">1、HTTP缓存原理 <a class="header-anchor" href="#_1、http缓存原理" aria-label="Permalink to &quot;1、HTTP缓存原理&quot;">​</a></h2><p>HTTP缓存分为<strong>强缓存</strong>和<strong>协商缓存</strong></p><h3 id="强缓存" tabindex="-1">强缓存 <a class="header-anchor" href="#强缓存" aria-label="Permalink to &quot;强缓存&quot;">​</a></h3><p>在第一次请求此资源时，在响应头读取<strong>Expires(http1.0)</strong> 过期时间，或者<strong>Cache-Control(http1.1 - 优先)</strong> 的max-age。如果在有效期内或者在缓存时间内，则命中强缓存。</p><p>1、浏览器从本地加载资源</p><h3 id="协商缓存" tabindex="-1">协商缓存 <a class="header-anchor" href="#协商缓存" aria-label="Permalink to &quot;协商缓存&quot;">​</a></h3><p><strong>ETag和If-None-Match（优先）：</strong> 在上一次的请求响应头中，会返回一个ETag（标识内容是否变化Hash），然后在本次请求中携带ETag，存储在请求头的If-None-Match里。服务器接收到该值进行比对，如未更改则返回304；更改则返回资源。</p><p><strong>Last-Modified 和 If-Modified-Since ：</strong> 在上一次的请求响应头中，会返回一个Last-Modified（标识内容上一次修改的时间(秒)），然后在本次请求中携带Last-Modified，存储在请求头的If-Modified-Since里。服务器接收到该值进行比对，如未更改则返回304；更改则返回资源。</p><p>1、浏览器携带请求参数，向后端发起请求，后端判断资源是否更改。</p><p>2、没有更改则响应头返回304，浏览器从本地加载资源</p><p>3、更改则直接返回最新资源及状态码200</p><h2 id="_2、get和post的区别" tabindex="-1">2、Get和Post的区别 <a class="header-anchor" href="#_2、get和post的区别" aria-label="Permalink to &quot;2、Get和Post的区别&quot;">​</a></h2><p><strong>1、请求参数：</strong></p><p>Get请求参数是放在url里面的，受限于url的长度限制，且数据直接暴露在url里相对不安全</p><p>Post是放在请求体里面，参数没有长度限制，且数据相对安全</p><p><strong>2、幂等性，缓存：</strong></p><p>Get请求时幂等的，且响应结果是可以被缓存</p><p>Post请求不是幂等的，可以进行多次提交，且不可以被缓存</p><p>Get请求一般用于获取数据，Post一般用于修改数据。</p>',20),n=[s];function i(p,d,h,c,l,_){return a(),e("div",null,n)}const u=t(r,[["render",i]]);export{f as __pageData,u as default};
